// ValidateHost validates all fields in Host according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateHost(m *Host) error {
	return ValidateHostWithDepth(m, 0)
}

// ValidateHostWithDepth validates Host and carries nested-message depth across
// generated package boundaries.
func ValidateHostWithDepth(m *Host, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate Host (assert_required)
	if m.Host == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field Host is required")
	}

	// Validate Host (assert_host: IP address or FQDN)
	if m.Host != "" {
		if ip := net.ParseIP(m.Host); ip == nil {
			if err := utils.ValidateAssertFQDN(m.Host); err != nil {
				return protoerrors.NewErrMissingInvalidData(nil, "field Host must be a valid IP address or FQDN, got: %s", m.Host)
			}
		}
	}

	// Validate Port (assert_net_port)
	if m.Port < 0 || m.Port > 65535 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Port must be a valid port number (0-65535), got: %d", m.Port)
	}

	// Validate Host (default max size: 32768 bytes)
	if len(m.Host) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Host exceeds max size of 32768 bytes, got: %d", len(m.Host))
	}

	// Validate Protocol enum value is known
	if _, ok := Protocol_name[int32(m.Protocol)]; !ok {
		return protoerrors.NewErrMissingInvalidData(nil, "field Protocol has unknown enum value %d", int32(m.Protocol))
	}

	return nil
}

